  if (run.env.PREVIEW_WORKERS?.trim()) settings.preview.workers = count(run.env.PREVIEW_WORKERS);
  for (const arg of run.argv) {
    if (!arg.startsWith('--workers=')) throw new Error('Unknown argument');
