  controller.abort(new Error('late cancellation'));
  assert.deepEqual(log, [
    'take1',
    'resolve1',
    'sink:first:0',
    'take2',
    'resolve2',
    'take3',
    'resolve3',
    'sink:second:1',
    'close',
  ]);
});

