export function createMemo(fetchValue) {
  const cache = new Map();

  return {
    get(key) {
      if (cache.has(key)) return cache.get(key);

      const pending = Promise.resolve()
        .then(() => fetchValue(key))
        .catch(error => {
          cache.delete(key);
          throw error;
        });

      cache.set(key, pending);
      return pending;
    },

    has(key) {
      return cache.has(key);
    }
  };
}
