function mapReadings(source, mapper, options) {
  const concurrency = options.concurrency;

  if (
    !Number.isInteger(concurrency) ||
    concurrency < 1 ||
    concurrency > 3
  ) {
    return Promise.reject(new RangeError("concurrency must be an integer from 1 to 3"));
  }

  const signal = options.signal;

  if (signal.aborted) {
    return Promise.reject(signal.reason);
  }

  return new Promise((resolve, reject) => {
    let iterator;
    let done = false;
    let settled = false;
    let returned = false;
    let active = 0;
    let index = 0;
    const results = [];

    const cleanup = () => {
      signal.removeEventListener("abort", onAbort);
    };

    const closeIterator = () => {
      if (!done && !returned) {
        returned = true;
        iterator.return?.();
      }
    };

    const settleReject = (reason) => {
      if (settled) return;
      settled = true;
      cleanup();
      closeIterator();
      reject(reason);
    };

    const settleResolve = () => {
      if (settled) return;
      settled = true;
      cleanup();
      resolve(results);
    };

    function onAbort() {
      settleReject(signal.reason);
    }

    signal.addEventListener("abort", onAbort);

    if (signal.aborted) {
      settleReject(signal.reason);
      return;
    }

    iterator = source[Symbol.iterator]();

    const fill = () => {
      while (!settled && !done && active < concurrency) {
        if (signal.aborted) {
          settleReject(signal.reason);
          return;
        }

        const item = iterator.next();

        if (item.done) {
          done = true;
          break;
        }

        const position = index++;
        let mapped;

        try {
          mapped = mapper(item.value, position);
        } catch (error) {
          settleReject(error);
          return;
        }

        active++;

        Promise.resolve(mapped).then(
          (value) => {
            if (settled) return;

            results[position] = value;
            active--;

            if (done && active === 0) {
              settleResolve();
            } else {
              fill();
            }
          },
          (reason) => {
            settleReject(reason);
          }
        );
      }

      if (!settled && done && active === 0) {
        settleResolve();
      }
    };

    fill();
  });
}
