import { readState, writeState } from './store.js';
import { validateState } from './schema.js';
import { encode } from './wire.js';
import { checkpoint } from './runtime.js';

const own = (value, key) => Object.prototype.hasOwnProperty.call(value, key);
const record = value => value !== null && typeof value === 'object' && !Array.isArray(value);

function invalidBackup() {
  const error = new Error('Invalid backup');
  error.code = 'INVALID_BACKUP';
  return error;
}

/*
 * Select the fields that belong to the interchange contract.  Besides making
 * the v1 rename explicit, this prevents incidental fields in an input document
 * from becoming part of the on-disk state.
 */
function makeState(options, books, assets, pageKey) {
  if (!record(options) || !Array.isArray(books) || !record(assets)) throw invalidBackup();

  const notebooks = books.map(book => {
    if (!record(book) || !own(book, 'id') || !own(book, 'label') || !own(book, pageKey) || !Array.isArray(book[pageKey])) {
      throw invalidBackup();
    }
    return {
      id: book.id,
      label: book.label,
      pages: book[pageKey].map(page => {
        const bodyKey = pageKey === 'pages' ? 'body' : 'text';
        if (!record(page) || !own(page, 'id') || !own(page, bodyKey) || !own(page, 'marks')) throw invalidBackup();
        return { id: page.id, body: page[bodyKey], marks: page.marks };
      })
    };
  });

  const state = { options, notebooks, assets };
  // Keep the storage schema as the single authority for state validity.
  try { return validateState(state); }
  catch { throw invalidBackup(); }
}

function decodeBackup(bytes) {
  if (!Buffer.isBuffer(bytes)) throw invalidBackup();

  let document;
  try {
    // A fatal decoder makes malformed UTF-8 an invalid backup instead of
    // silently replacing bytes before JSON parsing.
    document = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes));
  } catch {
    throw invalidBackup();
  }

  if (!record(document) || document.format !== 'field-pack') throw invalidBackup();
  if (document.version === 2) {
    if (!own(document, 'payload') || !record(document.payload)) throw invalidBackup();
    const { payload } = document;
    if (!own(payload, 'options') || !own(payload, 'notebooks') || !own(payload, 'assets')) throw invalidBackup();
    return makeState(payload.options, payload.notebooks, payload.assets, 'pages');
  }
  if (document.version === 1) {
    if (!own(document, 'options') || !own(document, 'books') || !own(document, 'assets')) throw invalidBackup();
    return makeState(document.options, document.books, document.assets, 'leaves');
  }
  throw invalidBackup();
}

export async function exportBackup(directory) {
  const state = await readState(directory);
  return encode({ format: 'field-pack', version: 2, payload: state });
}

export async function importBackup(directory, bytes) {
  const state = decodeBackup(bytes);
  const pages = state.notebooks.flatMap(book => book.pages);

  // No live generation is selected until every lifecycle checkpoint returns.
  for (let index = 0; index < pages.length; index += 1) checkpoint(index + 1);
  await writeState(directory, state);
  return { imported: pages.length };
}

